import{c as e,Q as t,j as a,m as i}from"./chunks/framework.DOi4mjdC.js";const n="/assets/%E7%AE%97%E5%AD%90%E5%BC%80%E5%8F%91%E7%AB%AF%E5%88%B0%E7%AB%AF%E6%B5%81%E7%A8%8B.UY7AOsEs.png",c=JSON.parse('{"title":"概述","description":"","frontmatter":{},"headers":[{"level":1,"title":"概述","slug":"概述"}],"relativePath":"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/概述.md","filePath":"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/概述.md"}'),r={name:"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/概述.md"};function s(o,l,p,h,A,_){return t(),a("div",null,[...l[0]||(l[0]=[i('<h1 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h1><p>工程化算子开发是指基于自动生成的<strong>自定义算子工程</strong>完成算子实现、编译部署、单算子调用代码自动生成等一系列流程。</p><p>该开发流程是标准的开发流程，建议开发者按照该流程进行算子开发。该方式下，算子开发的代码会更规范、统一、易于维护；同时该方式考虑了单算子API调用、算子入图、AI框架调用等功能的集成，使得开发者易于借助CANN框架实现上述功能。</p><p>工程化算子开发流程如下图所示：</p><p><img src="'+n+'" alt=""></p><ol><li><p>环境准备。</p><ol><li>CANN软件安装请参考<a href="./../../../../入门教程/环境准备.html">环境准备</a>。</li><li><a href="./创建算子工程.html">创建算子工程</a>。使用msOpGen工具创建算子开发工程。</li></ol></li><li><p>算子实现。</p><ul><li><a href="./算子原型定义.html">算子原型定义</a>。通过原型定义来描述算子输入输出、属性等信息以及算子在AI处理器上相关实现信息，并关联tiling实现等函数。</li><li>Kernel侧算子实现和host侧tiling实现请参考<a href="./../../../../算子实践参考/SIMD算子实现/概述.html">SIMD算子实现</a>；工程化算子开发，支持开发者调用Tiling API基于CANN提供的编程框架进行tiling开发，kernel侧也提供对应的接口方便开发者获取tiling参数，具体内容请参考<a href="./Kernel侧算子实现.html">Kernel侧算子实现</a>和<a href="./Host侧Tiling实现/基本流程.html">Host侧Tiling实现</a>，由此而带来的额外约束也在上述章节说明。</li></ul></li><li><p>编译部署。通过工程编译脚本完成算子的编译部署，分为<a href="./算子包编译/算子工程编译.html">算子包编译</a>和<a href="./算子动态库和静态库编译.html">算子动态库编译</a>两种方式。</p></li><li><p><a href="./单算子API调用.html">单算子API调用</a>：调用单算子API接口，基于C语言的API执行算子。</p></li></ol>',6)])])}const f=e(r,[["render",s]]);export{c as __pageData,f as default};
